"""Topology-adaptation evaluation: does each trained model run, and how does
it behave, when the twin's edges change?

The REAL Kelmarsh data contains exactly ONE topology (each source on its
primary bus). Reroutes/isolations only exist as twin decisions during replay,
and there is no ground-truth fault label that depends on topology. So this
script is honest about what it can and cannot show:

  * SYNTHETIC: every non-default edge set here is generated by applying the
    twin's own primitives (DigitalTwin.reroute_node / isolate_node) to private
    twin instances. Node features and labels are the REAL held-out test data;
    only the graph is synthetic. Nothing here enters the headline metrics.
  * It demonstrates (1) the same saved weights run on many different edge sets
    with no code change, and (2) how stable detection quality / scores are
    under topology change.
  * It CANNOT show that TA-GNN's topology-adaptive filters help on real
    topology-dependent faults, because no such labels exist in this data.

    venv\\Scripts\\python -m ai.topology_eval [--variants 60] [--kinds tag gcn mlp]
"""

from __future__ import annotations

import argparse
import itertools
import json
import warnings
from pathlib import Path

import numpy as np
import torch

warnings.filterwarnings("ignore", message=".*torch.jit.script.*")

from ai import dataset as D  # noqa: E402
from ai import features as F  # noqa: E402
from ai import metrics as M  # noqa: E402
from ai import training as T  # noqa: E402
from ai.models import NodeClassifier  # noqa: E402
from ai.run_experiments import ARTIFACT_DIR  # noqa: E402

SOURCES = [n for n in F.NODE_ORDER if n not in ("bus_a", "bus_b", "grid")]
ROUTES = ("bus_a", "bus_b", "isolated")


def make_variant(assignment: dict[str, str]) -> np.ndarray:
    """Edge index of a twin state where each source uses the given route,
    built with the twin's real mutation primitives on a private instance."""
    from app.twin.digital_twin import DigitalTwin

    twin = DigitalTwin()
    for node_id, route in assignment.items():
        if route == "isolated":
            twin.isolate_node(node_id)
        elif route != twin.get_node(node_id)["active_connection"]:
            twin.reroute_node(node_id, route)
    return F.edge_index_from_edges(twin.get_edges())


def sample_variants(n: int, seed: int = 0) -> list[dict[str, str]]:
    space = list(itertools.product(ROUTES, repeat=len(SOURCES)))  # 3^6 = 729 reachable routing states
    rng = np.random.default_rng(seed)
    pick = rng.choice(len(space), size=min(n, len(space)), replace=False)
    return [dict(zip(SOURCES, space[i])) for i in pick]


def load_artifact(kind: str):
    d = ARTIFACT_DIR / kind
    meta = json.loads((d / "meta.json").read_text())
    model = NodeClassifier(**meta["model_config"])
    model.load_state_dict(torch.load(d / "model.pt", weights_only=True))
    model.eval()
    return model, meta


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("--variants", type=int, default=60)
    ap.add_argument("--kinds", nargs="+", default=["tag", "gcn", "mlp"])
    args = ap.parse_args()

    arr = D.build_arrays()
    labels = D.make_labels(arr)
    splits = D.make_splits(arr)
    idx = splits.test
    y, valid = labels.y[idx], labels.valid[idx]
    m = valid

    static, default_edges = F.default_topology()
    variants = sample_variants(args.variants)
    edge_sets = [make_variant(v) for v in variants]
    n_edges = [e.shape[1] // 2 for e in edge_sets]
    n_distinct = len({e.tobytes() for e in edge_sets})
    n_isolated = [sum(1 for r in v.values() if r == "isolated") for v in variants]
    print(f"SYNTHETIC topology variants: {len(edge_sets)} sampled from 3^6=729 reachable routing states; "
          f"{n_distinct} distinct edge sets; undirected edges per graph min/median/max = "
          f"{min(n_edges)}/{int(np.median(n_edges))}/{max(n_edges)}; isolated sources per graph 0..{max(n_isolated)}")

    report = {
        "synthetic": True,
        "note": "Real test-set features/labels on SYNTHETIC topologies (twin reroute/isolate primitives). Not headline metrics.",
        "n_variants": len(edge_sets),
        "n_distinct_edge_sets": n_distinct,
        "edges_per_graph": {"min": min(n_edges), "median": int(np.median(n_edges)), "max": max(n_edges)},
        "models": {},
    }
    for kind in args.kinds:
        model, meta = load_artifact(kind)
        norm = F.Normalizer.from_dict(meta["normalizer"])
        x = D.snapshot_tensor(arr, idx, norm, static)
        thr = meta["threshold_logit"]
        base = T.predict_logits(model, x, default_edges)
        base_auc, base_pr = M.roc_auc(y[m], base[m]), M.pr_auc(y[m], base[m])
        base_f1 = M.prf(y[m], (base >= thr)[m])["f1"]
        aucs, prs, f1s, drifts = [], [], [], []
        for e in edge_sets:
            lg = T.predict_logits(model, x, e)
            aucs.append(M.roc_auc(y[m], lg[m]))
            prs.append(M.pr_auc(y[m], lg[m]))
            f1s.append(M.prf(y[m], (lg >= thr)[m])["f1"])
            drifts.append(float(np.abs(lg[m] - base[m]).mean()))
        report["models"][kind] = {
            "default_topology": {"roc_auc": base_auc, "pr_auc": base_pr, "f1_at_val_threshold": base_f1},
            "varied_topologies": {
                "roc_auc": {"mean": float(np.mean(aucs)), "min": float(np.min(aucs)), "max": float(np.max(aucs))},
                "pr_auc": {"mean": float(np.mean(prs)), "min": float(np.min(prs)), "max": float(np.max(prs))},
                "f1_at_val_threshold": {"mean": float(np.mean(f1s)), "min": float(np.min(f1s)), "max": float(np.max(f1s))},
                "mean_abs_logit_shift_vs_default": {"mean": float(np.mean(drifts)), "max": float(np.max(drifts))},
            },
        }
        v = report["models"][kind]["varied_topologies"]
        print(f"\n{meta['display_name']}: default ROC-AUC {base_auc:.3f} PR-AUC {base_pr:.3f} F1 {base_f1:.3f}")
        print(f"   over {len(edge_sets)} synthetic topologies: ROC-AUC {v['roc_auc']['mean']:.3f} "
              f"[{v['roc_auc']['min']:.3f}, {v['roc_auc']['max']:.3f}]  PR-AUC {v['pr_auc']['mean']:.3f} "
              f"[{v['pr_auc']['min']:.3f}, {v['pr_auc']['max']:.3f}]  F1 {v['f1_at_val_threshold']['mean']:.3f} "
              f"| mean |logit shift| {v['mean_abs_logit_shift_vs_default']['mean']:.3f}")

    out = ARTIFACT_DIR / "topology_eval.json"
    out.write_text(json.dumps(report, indent=2))
    print(f"\nwrote {out}")


if __name__ == "__main__":
    main()
